prologue:
/* Levels the player has opened live in packs.sav as a plain list of ids, so a sheet walks it
   by number, and a name is how it finds one again */
static MOD_UNUSED const char* sav_level_at(int index) {
    const char* name = API->sav != 0 ? API->sav->NameAt(SELF, index) : 0;
    return name != 0 ? name : "";
}

static MOD_UNUSED int sav_find(const char* level) {
    const int count = API->sav != 0 ? API->sav->Count(SELF) : 0;
    int at;
    for (at = 0; at < count; ++at)
        if (strcmp(sav_level_at(at), level) == 0) return at;
    return -1;
}

/* A disk slot says what it holds without being loaded */
static MOD_UNUSED const char* sav_slot_name(int slot) {
    const char* name = API->sav != 0 ? API->sav->SlotName(SELF, slot) : 0;
    return name != 0 ? name : "";
}

static MOD_UNUSED const char* sav_slot_level(int slot) {
    const char* name = API->sav != 0 ? API->sav->SlotLevel(SELF, slot) : 0;
    return name != 0 ? name : "";
}

static MOD_UNUSED int sav_slots_used(void) {
    int at, used = 0;
    if (API->sav == 0) return 0;
    for (at = 0; at < 100; ++at) used += API->sav->SlotExists(SELF, at) != 0;
    return used;
}

static MOD_UNUSED int sav_free_slot(void) {
    int at;
    if (API->sav == 0) return -1;
    for (at = 0; at < 100; ++at)
        if (API->sav->SlotExists(SELF, at) == 0) return at;
    return -1;
}

/* What this mod keeps inside a save of its own: numbers under names of the mod's choosing.
   The whole table is written as one lump when the game saves, and read back when it loads,
   so a sheet only ever says "remember this number" and "what was remembered" */
enum { kSavNumbers = 16, kSavNameLen = 24 };

typedef struct SavNumber {
    char name[kSavNameLen];
    float value;
} SavNumber;

static SavNumber g_sav_numbers[kSavNumbers];

static MOD_UNUSED int sav_number_slot(const char* name, int make) {
    int at, free_slot = -1;
    if (name == 0 || name[0] == 0) return -1;
    for (at = 0; at < kSavNumbers; ++at) {
        if (g_sav_numbers[at].name[0] == 0) {
            if (free_slot < 0) free_slot = at;
            continue;
        }
        if (strcmp(g_sav_numbers[at].name, name) == 0) return at;
    }
    if (make == 0 || free_slot < 0 || strlen(name) >= kSavNameLen) return -1;
    strcpy(g_sav_numbers[free_slot].name, name);
    g_sav_numbers[free_slot].value = 0.0f;
    return free_slot;
}

static MOD_UNUSED void sav_set_number(const char* name, float value) {
    const int slot = sav_number_slot(name, 1);
    if (slot >= 0) g_sav_numbers[slot].value = value;
}

static MOD_UNUSED float sav_number(const char* name) {
    const int slot = sav_number_slot(name, 0);
    return slot >= 0 ? g_sav_numbers[slot].value : 0.0f;
}

static MOD_UNUSED int sav_has_number(const char* name) {
    return sav_number_slot(name, 0) >= 0;
}

static MOD_UNUSED void sav_forget_numbers(void) {
    memset(g_sav_numbers, 0, sizeof g_sav_numbers);
}

/* Only inside the save event: everything remembered goes into the tail of the slot file */
static MOD_UNUSED void sav_write_numbers(void) {
    if (API->sav != 0) API->sav->WriteSlotData(SELF, g_sav_numbers, (int)sizeof g_sav_numbers);
}

/* Only inside the load event: the same lump, read back. A save written by an older mod is
   shorter, so only as much as came is taken */
static MOD_UNUSED void sav_read_numbers(const void* bytes, int size) {
    if (bytes == 0 || size <= 0) return;
    if (size > (int)sizeof g_sav_numbers) size = (int)sizeof g_sav_numbers;
    memset(g_sav_numbers, 0, sizeof g_sav_numbers);
    memcpy(g_sav_numbers, bytes, (size_t)size);
}

/* A change the mod made to a level, kept per slot under a name the mod chooses. AzForge only
   remembers it; putting the door back where it was is the sheet's own business */
static MOD_UNUSED int sav_change(const char* level, const char* name, int fallback) {
    return API->sav != 0 ? API->sav->GetLevelChange(SELF, level, name, fallback) : fallback;
}

static MOD_UNUSED int sav_change_read(int index, AmodLevelChange* out) {
    if (API->sav == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->sav->LevelChangeAt(SELF, index, out);
}

static MOD_UNUSED const char* sav_change_name(int index) {
    AmodLevelChange change;
    if (sav_change_read(index, &change) == 0 || change.name == 0) return "";
    return change.name;
}

static MOD_UNUSED const char* sav_change_level(int index) {
    AmodLevelChange change;
    if (sav_change_read(index, &change) == 0 || change.level == 0) return "";
    return change.level;
}

static MOD_UNUSED int sav_change_value(int index) {
    AmodLevelChange change;
    return sav_change_read(index, &change) != 0 ? change.value : 0;
}

/* What a room of a slot holds. A thing is read by its place in the room; 0 is its tag,
   1 how many bytes it takes, 2 to 4 the three values it keeps */
static MOD_UNUSED int sav_room_thing(int slot, int room, int index, int which) {
    AmodRoomThing thing;
    if (API->sav == 0) return 0;
    memset(&thing, 0, sizeof thing);
    thing.structSize = sizeof thing;
    if (API->sav->GetSlotRoomThing(SELF, slot, room, index, &thing) == 0) return 0;
    if (which == 0) return thing.tag;
    if (which == 1) return thing.saved;
    if (which >= 2 && which <= 4) return thing.values[which - 2];
    return 0;
}

static MOD_UNUSED void sav_set_room_thing(int slot, int room, int index, int first, int second,
                                          int third) {
    AmodRoomThing thing;
    if (API->sav == 0) return;
    memset(&thing, 0, sizeof thing);
    thing.structSize = sizeof thing;
    if (API->sav->GetSlotRoomThing(SELF, slot, room, index, &thing) == 0) return;
    thing.values[0] = first;
    thing.values[1] = second;
    thing.values[2] = third;
    API->sav->SetSlotRoomThing(SELF, slot, room, index, &thing);
}

/* 0 whether the room writes anything, 1 the byte it keeps, 2 whether the extra goes too,
   3 the extra itself */
static MOD_UNUSED int sav_room_memory(int slot, int room, int which) {
    AmodRoomMemory memory;
    if (API->sav == 0) return 0;
    memset(&memory, 0, sizeof memory);
    memory.structSize = sizeof memory;
    if (API->sav->GetSlotRoomMemory(SELF, slot, room, &memory) == 0) return 0;
    if (which == 0) return memory.isSaved;
    if (which == 1) return memory.state;
    if (which == 2) return memory.hasExtra;
    return memory.extra;
}

static MOD_UNUSED void sav_set_room_memory(int slot, int room, int state, int extra) {
    AmodRoomMemory memory;
    if (API->sav == 0) return;
    memset(&memory, 0, sizeof memory);
    memory.structSize = sizeof memory;
    if (API->sav->GetSlotRoomMemory(SELF, slot, room, &memory) == 0) return;
    memory.state = state;
    memory.extra = extra;
    memory.hasExtra = 1;
    API->sav->SetSlotRoomMemory(SELF, slot, room, &memory);
}

/* What pack_NNN.mis describes: its id, name, menu script and preview texture */
static MOD_UNUSED int sav_pack_read(int pack, AmodPack* out) {
    if (API->sav == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->sav->GetPack(SELF, pack, out);
}

static MOD_UNUSED int sav_pack_id(int pack) {
    AmodPack info;
    return sav_pack_read(pack, &info) != 0 ? info.id : 0;
}

static MOD_UNUSED const char* sav_pack_name(int pack) {
    AmodPack info;
    if (sav_pack_read(pack, &info) == 0 || info.name == 0) return "";
    return info.name;
}

static MOD_UNUSED const char* sav_pack_menu(int pack) {
    AmodPack info;
    if (sav_pack_read(pack, &info) == 0 || info.menuScript == 0) return "";
    return info.menuScript;
}

static MOD_UNUSED const char* sav_pack_preview(int pack) {
    AmodPack info;
    if (sav_pack_read(pack, &info) == 0 || info.preview == 0) return "";
    return info.preview;
}

static int g_sav_last_slot = 0;

static MOD_UNUSED void __cdecl sav_save_relay(int slot, void* user) {
    g_sav_last_slot = slot;
    if (user != 0) ((AmodSlotSaveHandler)user)(slot, 0);
}

static MOD_UNUSED void __cdecl sav_load_relay(int slot, const void* bytes, int size, void* user) {
    g_sav_last_slot = slot;
    if (user != 0) ((AmodSlotLoadHandler)user)(slot, bytes, size, 0);
}

static MOD_UNUSED int sav_event_slot(void) {
    return g_sav_last_slot;
}
